css:
.aha-scale{
  font-family:var(--aha-font-product);
  color:var(--aha-text-default);
  display:flex;
  flex-direction:column;
  gap:var(--aha-space-12);
}
.aha-scale__row{
  display:grid;
  grid-template-columns:7rem 1fr auto;
  align-items:center;
  gap:var(--aha-space-16);
}
.aha-scale__name{font-size:var(--aha-size-default);font-weight:var(--aha-weight-semibold);color:var(--aha-text-secondary)}
.aha-scale__bar{
  height:var(--aha-space-16);
  min-width:var(--aha-space-2);
  background:var(--aha-color-primary);
  border-radius:var(--aha-radius-xs);
  display:block;
}
.aha-scale__val{font-family:var(--aha-font-mono);font-size:var(--aha-size-sm);color:var(--aha-text-tertiary)}
